#include "app/Application.hpp"
namespace airmuse { Application::Application()=default;Application::~Application(){providers_.Shutdown();} Result<void> Application::Start(){auto mock=std::make_shared<MockProvider>();auto r=providers_.Register(mock);if(!r)return r;MediaSnapshot demo;demo.sessionId="demo";demo.title="AirMuse";demo.artist="Waiting for a media provider";demo.duration=Milliseconds(240000);demo.status=PlaybackStatus::Paused;demo.capabilities=mock->GetCapabilities();mock->AddSession(std::move(demo));return Result<void>::Ok();} void Application::TogglePlayback(){auto s=coordinator_.Active();if(s)coordinator_.Dispatch(s->status==PlaybackStatus::Playing?PlaybackCommand::Pause:PlaybackCommand::Play);} }
